namespace Fanex.Age.UI.TotalBets
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Data;
    using System.IO;
    using System.Text;
    using System.Web.UI;
    using Fanex.Age.UI.Components;
    using Fanex.BetList.Age.BetListCmd;
    using Fanex.BetList.Age.BetListExcelBuilderExt;
    using Fanex.BetList.Age.BetListHTMLBuilderExt;
    using Fanex.BetList.Age.Definition;
    using Fanex.BetList.Age.DTO;
    using Fanex.BetList.Age.ExtTemplate;
    using Fanex.BetList.Core.Builder;
    using Fanex.BetList.Core.Entities;
    using Fanex.BetList.Core.Factories;
    using Fanex.BetList.Core.TicketHelper;
    using NPOI.SS.UserModel;
    using Sunplus.Agent.Model.BL.Definitions;
    using Sunplus.Agent.Model.BL.Forecast;
    using Sunplus.Agent.Model.BL.TotalBets;
    using Sunplus.Agent.Model.Entities;
    using Sunplus.Agent.Utilities;

    /// <summary>
    /// This report is currently not applied to Age site so there're some notes need to be
    /// considered:
    /// 1) It is not tested
    /// 2) It is implemented basing on typical report pages
    /// so the business might be slightly different in later implementations
    /// </summary>

    public partial class OtherBettypes_Page : Fanex.Age.UI.Reports.WinlossReports_Page
    {
        private string type = string.Empty;
        private bool exportExcel = false;
        private IBetListCmd command = null;

        private int custId;
        private int bettype;
        private DateTime dateFrom, dateTo;

        public override void RenderContent(HtmlTextWriter writer)
        {
            #region INIT

            UserTypes userType = UserTypes.Unknown;
            if (CurrentUserSession.IsSuper)
            {
                userType = UserTypes.Super;
            }
            else if (CurrentUserSession.IsMaster)
            {
                userType = UserTypes.Master;
            }
            else if (CurrentUserSession.IsAgent)
            {
                userType = UserTypes.Agent;
            }

            bool isShowWinLost = true,
                 isShowSuperPT = true,
                 isShowMasterPT = true,
                 isShowAgentPT = true,
                 isShowMember = true;

            //Other bettypes betlist => not show WinLoss, Member
            isShowWinLost = isShowMember = false;

            switch (userType)
            {
                case UserTypes.Super:
                    break;
                case UserTypes.Master:
                    isShowSuperPT = false;
                    break;
                case UserTypes.Agent:
                    isShowSuperPT = isShowMasterPT = false;
                    break;
                default: // Hide all position taking
                    isShowSuperPT = isShowMasterPT = isShowAgentPT = false;
                    break;
            }

            DataTable betListData = View as DataTable;
            IList<ITicket> tickets = new List<ITicket>();

            if (betListData != null)
            {
                tickets = TicketTransformer.Transform(betListData);
                betListData.Dispose();
            }

            DataTable commandData = this.command.OutDataTable();
            List<ITicketData> ticketData = new List<ITicketData>();

            if (commandData != null)
            {
                ticketData = TicketDataTransformer.Transform(commandData);
                commandData.Dispose();
            }

            #endregion

            #region Customize

            short excelColumns = 11;

            Header1_Template betlistHeader = new Header1_Template();

            if (!isShowSuperPT)
            {
                excelColumns--;
                betlistHeader.Super.Hide();
            }

            if (!isShowMasterPT)
            {
                excelColumns--;
                betlistHeader.Master.Hide();
            }

            if (!isShowAgentPT)
            {
                excelColumns--;
                betlistHeader.Agent.Hide();
            }

            if (!isShowMember)
            {
                excelColumns--;
                betlistHeader.Member.Hide();
            }

            if (!isShowWinLost)
            {
                excelColumns--;
                betlistHeader.Winloss.Hide();
            }

            string reportTitle = Resources.Lang.lblOtherTypes;

            #endregion

            int index = 0;
            bool isAdminCanViewVNIP = UserSession.Current.IsAdminCanViewVNIP;

            if (this.exportExcel)
            {
                #region EXPORT EXCEL

                GetCachePropertyById funcGetOddsTypeName = CacheRef.GetOddsTypeName;
                ITicketHelper ticketHelper = new TicketHelper();
                BetListExcelFactory factory = new BetListExcelFactory();
                BetListExcelBuilder builder = factory.CreateBuilder();

                builder.BuildWorksheet("BetList", excelColumns);
                builder.AddCaption(reportTitle, excelColumns);
                builder.AddHeader(isShowWinLost, isShowSuperPT, isShowMasterPT, isShowAgentPT, isShowMember);

                foreach (ITicket ticket in tickets)
                {
                    index++;
                    ticketHelper.Index = index;

                    builder
                        .AddNo(index);
                    if (isShowMember)
                    {
                        builder.AddMember(ticket, ticketHelper);
                    }

                    builder.AddTrans(ticket, ticketHelper);

                    builder
                        .AddChoice(ticket, ticketHelper, ticketData)
                        .AddOdds(ticket, ticketData, funcGetOddsTypeName)
                        .AddStake(ticket, ticketHelper);

                    if (isShowWinLost)
                    {
                        builder.AddWinLoss(ticket);
                    }

                    builder
                        .AddStatus(ticket, ticketHelper, ticketData, isAdminCanViewVNIP);

                    if (isShowSuperPT)
                    {
                        builder.AddSuperPT(ticket, ticketData);
                    }

                    if (isShowMasterPT)
                    {
                        builder.AddMasterPT(ticket, ticketData);
                    }

                    if (isShowAgentPT)
                    {
                        builder.AddAgentPT(ticket, ticketData);
                    }
                }


                if (tickets.Count == 0)
                {
                    builder.AddFooter(tickets, isShowMember, excelColumns);
                }

                MemoryStream ms = new MemoryStream();
                IWorkbook resultWorkbook = builder.GetBetList();
                resultWorkbook.Write(ms);

                ExportToExcel(ms, "BetList.xls");
                ms.Dispose();
                return;

                #endregion
            }
            else
            {
                #region RENDER HTML

                BetListTemplate tpl = new BetListTemplate();
                StringBuilder content = new StringBuilder();

                tpl.title = reportTitle;

                Fanex.BetList.Age.ExtTemplate.OpenBetList_Template betlistOpenTag = new Fanex.BetList.Age.ExtTemplate.OpenBetList_Template();
                content.Append(betlistOpenTag);

                content.Append(betlistHeader);
                content.Append("<tbody>");
                ForecastBO bo = new ForecastBO(UserSession.Current.NetSessionId);
                List<int> lstScoremap = bo.GetListBetTypeScoreMap();

                bool isShowScoremap;
                bool mode = ((BetListType)bettype & BetListType.SmartPhone) != BetListType.SmartPhone;
                GetCachePropertyById funcGetOddsTypeName = CacheRef.GetOddsTypeName;

                ITicketHelper ticketHelper = new TicketHelper();
                BetListHTMLFactory factory = new BetListHTMLFactory();
                BetListHTMLBuilder builder = factory.CreateBuilder();

                foreach (ITicket ticket in tickets)
                {
                    if (lstScoremap.Contains(ticket.BetTypeId) && ticket.Status.Equals(Fanex.BetList.Core.Entities.BetStatus.Running) && mode)
                    {
                        isShowScoremap = true;
                    }
                    else
                    {
                        isShowScoremap = false;
                    }

                    index++;
                    ticketHelper.Index = index;

                    builder.Append(string.Format("<tr id='{0}'>", ticket.TransId))
                           .AddNo(index, "<td class='w-order'>", "</td>");

                    if (isShowMember)
                    {
                        builder.AddMember(ticket, "<td class='c'>", "</td>");
                    }

                    builder
                            .AddTrans(ticket, "<td class='c nonbreak'>", "</td>")
                            .AddChoice(ticket, ticketHelper, ticketData, "<td class='r bl_evt'><div>", "</div></td>", isShowScoremap)
                            .AddOdds(ticket, ticketData, "<td class='bl_underdog nonbreak'>", "</td>", funcGetOddsTypeName)
                            .AddStake(ticket, "<td class='bl_underdog'>", "</td>");

                    if (isShowWinLost)
                    {
                        builder.AddWinLoss(ticket, "<td class='r nonbreak'>", "</td>");
                    }

                    builder.AddStatus(ticket, ticketHelper, ticketData, "<td class='c'>", "</td>", isAdminCanViewVNIP);

                    if (isShowSuperPT)
                    {
                        builder.AddSuperPT(ticket, ticketData, "<td class='r'>", "</td>");
                    }

                    if (isShowMasterPT)
                    {
                        builder.AddMasterPT(ticket, ticketData, "<td class='r'>", "</td>");
                    }

                    if (isShowAgentPT)
                    {
                        builder.AddAgentPT(ticket, ticketData, "<td class='r'>", "</td>");
                    }

                    builder.Append("</tr>");
                }

                builder.AddFooter(tickets, string.Empty, string.Empty, userType, BetListType.Default);

                content.Append(builder.GetBetList());
                content.Append("</tbody></table>");

                tpl.content = content.ToString();
                tpl.ToString(writer);

                RegisterJavascriptObject("type", type);
                RegisterJavascriptObject("fdate", dateFrom.ToShortDateString());
                RegisterJavascriptObject("tdate", dateTo.ToShortDateString());
                RegisterJavascriptObject("isHistoryReport", base._isHistoryReport == true ? 1 : 0);
                RenderFilterElementNames();

                #endregion
                
            }            
        }

        public override void ProcessRequest(ref Hashtable hash)
        {
            base.ProcessRequest(ref hash);

            type = Request["type"];

            if (!type.Equals("MixParlay") && !type.Equals("CombinationMixParlay"))
            {
                if (Request["fdate"] == null || Request["tdate"] == null)
                {
                    hash.Add("DateIsNull", true);
                }

                int.TryParse(Request["custid"] + string.Empty, out custId);
                int.TryParse(Request["bettype"] + string.Empty, out bettype);
                dateFrom = Cast.AsDateTime(Request["fdate"]);
                dateTo = Cast.AsDateTime(Request["tdate"]);

                hash.Add("language", Request["lang"] + string.Empty);
                hash.Add("username", Request["username"] + string.Empty);
                hash.Add("race", Request["race"] + string.Empty);
                hash.Add("matchid", Request["matchid"] != null ? int.Parse(Request["matchid"]) : 0);
                hash.Add("leagueid", Request["leagueid"] != null ? int.Parse(Request["leagueid"]) : 0);
                hash.Add("islive", Request["islive"] != null ? int.Parse(Request["islive"]) : 0);
                hash.Add("transtype", Request["transtype"] != null ? int.Parse(Request["transtype"]) : 0);
                hash.Add("betteam", Request["betteam"] + string.Empty);
            }
            else
            {
                dateFrom = DateTime.Now;
                dateTo = DateTime.Now;
            }

            exportExcel = Request["exporttoexcel.x"] != null ? true : false;
        }

        public override object ValidateRequest(Hashtable p)
        {
            if (Request["custid"] != null)
            {
                if (int.Parse(Request["custid"].ToString()) <= 0)
                {
                    return new ErrorPage_Page(Resources.Lang.strNotAccessPage);
                }
            }

            if (Request["bettype"] != null)
            {
                if (int.Parse(Request["bettype"].ToString()) < 0)
                {
                    return new ErrorPage_Page(Resources.Lang.strNotAccessPage);
                }
            }

            DateTime minDate = new DateTime(2000, 1, 1);
            DateTime maxDate = DateTime.Now.AddDays(30);

            if (dateFrom < minDate || dateTo < minDate || dateTo > maxDate) return new ErrorPage_Page(Resources.Lang.strNotAccessPage);

            return null;
        }

        public override object InvokeData(Hashtable p)
        {
            this.command = BetListFactory.CreateBetList(type, CurrentUserSession.NetSessionId, _permission);
            
            TotalBetsBO _TotalBetsBO = new TotalBetsBO(CurrentUserSession.NetSessionId);

            return _TotalBetsBO.GetOtherBettypes();
        }
    }
}